import {PvpClient} from './pvp-client.mjs?v=charge-pose-1';
import {PVP_SERVER} from './pvp-config.mjs';
export function mountPvpUI(hooks){
 const $=id=>document.getElementById(id),selection=$('selection'),card=selection.querySelector('.select-card');
 const tabs=document.createElement('div');tabs.className='mode-tabs';tabs.innerHTML='<button id="modeAI" aria-pressed="true">AI 연습</button><button id="modePvp" aria-pressed="false">친구와 대전</button>';card.prepend(tabs);
 const panel=document.createElement('section');panel.id='pvpPanel';panel.className='pvp-panel hidden';panel.innerHTML=`<p>선택한 세 마법을 모두 사용할 수 있습니다. 체력·마력·숙련도는 같은 조건으로 시작합니다. 몬스터는 나오지 않습니다.</p><div id="pvpConnect"><div class="pvp-row"><button id="createRoom" class="primary">방 만들기</button><label for="roomCode">방 코드</label><input id="roomCode" maxlength="6" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="6자리 코드"><button id="joinRoom">참가하기</button></div><details><summary>서버 연결 설정</summary><label for="pvpServer">대전 서버 주소</label><input id="pvpServer" type="url" placeholder="wss://서버주소/pvp"></details></div><div id="pvpRoom" class="hidden"><div class="pvp-row"><span>방 코드 <strong id="activeRoomCode"></strong></span><button id="copyRoom">초대 링크 복사</button><button id="leaveRoom">방 나가기</button></div><p id="roomPlayers"></p><button id="readyRoom" class="primary">대전 준비</button></div><p id="pvpStatus" role="status" aria-live="polite">방을 만들거나 친구의 방 코드를 입력하세요.</p>`;card.querySelector('.select-footer').before(panel);
 const headerButton=document.createElement('button');headerButton.id='onlineButton';headerButton.textContent='친구와 대전';document.querySelector('.actions').prepend(headerButton);
 const badge=document.createElement('div');badge.id='onlineStatus';badge.className='online-status hidden';document.body.append(badge);
 let mode='ai',code=null,ready=false,phase='waiting',busy=false,countdownTimer=null,pingTimer=null,lastTick=0;
 const status=text=>$('pvpStatus').textContent=text;
 const unlock=()=>{for(const b of card.querySelectorAll('[data-rune],[data-slot],[data-character]'))b.disabled=b.dataset.fixed==='true'||ready||phase==='countdown';};
 const client=new PvpClient(message=>{
  if(message.type==='joined'){code=message.code;$('activeRoomCode').textContent=code;$('pvpConnect').classList.add('hidden');$('pvpRoom').classList.remove('hidden');badge.classList.remove('hidden');headerButton.textContent='대전 방 보기';status('마법을 고른 뒤 대전 준비를 누르세요.');}
  if(message.type==='lobby'){phase=message.phase;ready=message.players[client.index]?.ready||false;$('roomPlayers').textContent=message.players.map((p,i)=>(i===client.index?'나':'친구')+': '+(!p?'입장 대기':p.ready?'준비 완료':'마법 선택 중')).join(' · ');$('readyRoom').textContent=ready?'준비 취소':'대전 준비';$('readyRoom').disabled=phase==='countdown'||phase==='playing';unlock();}
  if(message.type==='start'){clearInterval(countdownTimer);ready=true;phase='countdown';headerButton.textContent='방 나가기';$('readyRoom').disabled=true;unlock();hooks.start(message,client.index);selection.classList.add('hidden');let remaining=message.countdown;badge.textContent=`방 ${code} · ${remaining}초 뒤 시작`;countdownTimer=setInterval(()=>{remaining=Math.max(1,remaining-1);badge.textContent=`방 ${code} · ${remaining}초 뒤 시작`;},1000);}
  if(message.type==='go'){clearInterval(countdownTimer);phase='playing';lastTick=Date.now();badge.textContent=`방 ${code} · 1대1 대전`;hooks.go();}
  if(message.type==='tick'&&message.round===client.round){lastTick=Date.now();hooks.tick(message);if(message.state.finished){phase='ended';headerButton.textContent='대전 방 보기';}}
  if(message.type==='opponentLeft'){clearInterval(countdownTimer);phase='waiting';ready=false;hooks.stop();selection.classList.remove('hidden');status(message.message);}
  if(message.type==='error')status(message.message);
  if(message.type==='pong'&&phase==='playing')badge.textContent=`방 ${code} · 응답 ${Math.max(0,Date.now()-message.at)}ms`;
 },()=>{resetRoom();hooks.stop();selection.classList.remove('hidden');status('연결이 끊어져 경기가 종료됐습니다. 방을 다시 만들거나 참가하세요.');});
 function resetRoom(){clearInterval(countdownTimer);clearInterval(pingTimer);code=null;ready=false;phase='waiting';client.disconnect();$('pvpConnect').classList.remove('hidden');$('pvpRoom').classList.add('hidden');badge.classList.add('hidden');headerButton.textContent='친구와 대전';unlock();}
 function setMode(next){if(next==='ai'&&code){client.send({type:'leave'});resetRoom();hooks.stop();}mode=next;$('modeAI').setAttribute('aria-pressed',String(mode==='ai'));$('modePvp').setAttribute('aria-pressed',String(mode==='pvp'));panel.classList.toggle('hidden',mode!=='pvp');$('confirmSelection').classList.toggle('hidden',mode==='pvp');$('selectTitle').textContent='캐릭터와 보조 마법을 고르세요.';card.querySelector('.select-lead').textContent=mode==='pvp'?'캐릭터의 전문 1륜은 기본 마법으로 고정됩니다. 좌·우 클릭에 보조 마법을 고르면, 세 마법으로 대전합니다.':'캐릭터의 전문 1륜은 기본 마법으로 고정됩니다. 좌·우 클릭에는 사냥하며 배울 다른 1륜 두 개를 고르세요. 처음에는 공격 마법 하나만 사용합니다. 장벽 전문인 도윤은 첫 번째 보조 공격 마법부터 시작합니다.';hooks.mode(mode);}
 const local=location.hostname==='localhost'||location.hostname==='127.0.0.1';const base=new URL('pvp',new URL('./',location.href));base.protocol=location.protocol==='https:'?'wss:':'ws:';$('pvpServer').value=local?base.href:PVP_SERVER||base.href;
 async function connect(action){if(busy)return;const joinCode=$('roomCode').value.trim().toUpperCase();if(action==='join'&&!/^[A-Z2-9]{6}$/.test(joinCode)){status('6자리 방 코드를 입력하세요.');return;}let url;try{url=new URL($('pvpServer').value);if(!['ws:','wss:'].includes(url.protocol)||url.username||url.password)throw Error();if(location.protocol==='https:'&&url.protocol!=='wss:')throw Error();}catch{status('서버 주소를 확인하세요. HTTPS 페이지에서는 wss:// 주소가 필요합니다.');return;}busy=true;$('createRoom').disabled=$('joinRoom').disabled=true;status('서버에 연결하는 중입니다.');try{await client.connect(url.href);client.send(action==='create'?{type:'create'}:{type:'join',code:joinCode});clearInterval(pingTimer);pingTimer=setInterval(()=>{client.send({type:'ping',at:Date.now()});if(phase==='playing'&&Date.now()-lastTick>8000){client.disconnect();resetRoom();hooks.stop();selection.classList.remove('hidden');status('서버 응답이 멈췄습니다. 방에 다시 접속하세요.');}},2000);}catch(e){status(e.message);}finally{busy=false;$('createRoom').disabled=$('joinRoom').disabled=false;}}
 $('modeAI').onclick=()=>setMode('ai');$('modePvp').onclick=()=>setMode('pvp');$('createRoom').onclick=()=>connect('create');$('joinRoom').onclick=()=>connect('join');$('roomCode').addEventListener('keydown',e=>{if(e.key==='Enter')connect('join');});
 $('readyRoom').onclick=()=>client.send({type:'ready',ready:!ready,loadout:hooks.loadout()});
 $('leaveRoom').onclick=()=>{client.send({type:'leave'});resetRoom();hooks.stop();status('방에서 나왔습니다. 새 방을 만들거나 참가하세요.');};
 $('copyRoom').onclick=async()=>{const url=new URL(location.href);url.searchParams.set('room',code);try{await navigator.clipboard.writeText(url.href);status('초대 링크를 복사했습니다. 친구에게 보내세요.');}catch{status('초대 링크: '+url.href);}};
 headerButton.onclick=()=>{if(phase==='playing'||phase==='countdown'){client.send({type:'leave'});resetRoom();hooks.stop();}hooks.open();setMode('pvp');};
 // Text fields must never enqueue spells or change the selected rune slot.
 for(const input of panel.querySelectorAll('input'))input.addEventListener('keydown',e=>e.stopPropagation());
 const room=new URL(location.href).searchParams.get('room');if(room){$('roomCode').value=room.toUpperCase().slice(0,6);setMode('pvp');}
 return {get locked(){return ready||phase==='countdown';},get playing(){return phase==='playing';},get connected(){return !!code;},get mode(){return mode;},get index(){return client.index;},input:input=>{if(phase==='playing')client.input(input);},refresh:unlock,showRoom(){selection.classList.remove('hidden');$('result').classList.add('hidden');setMode('pvp');},open(){hooks.open();setMode('pvp');},leave(){client.send({type:'leave'});resetRoom();hooks.stop();setMode('ai');}};
}
